#define APP_TITLE "GX-TXT Curve Trace Assistant (native C)"
#define VERSION "0.5.0"
#define PANEL_W 360
#define STATUS_H 24
#define MAX_HITS 96

typedef struct { char *doc_id,*doc_sha,*cfg_id,*name,*source_id; int ready; } Config;
typedef struct { char *id,*name; } Curve;
typedef struct { int x,y,w,h,action; } Hit;

enum {
 A_CFG_PREV=1,A_CFG_NEXT,A_CURVE_PREV,A_CURVE_NEXT,A_RELOAD,A_FIT,A_SEED1,A_SEED2,A_CLEAR_SEEDS,
 A_TRACE,A_CANCEL,A_CLEAR_PROP,A_DIR,A_MODE,
 A_STEP_DEC,A_STEP_INC,A_RAD_DEC,A_RAD_INC,A_TOL_DEC,A_TOL_INC,A_SAMPLE_DEC,A_SAMPLE_INC,
 A_RING_DEC,A_RING_INC,A_AMB_DEC,A_AMB_INC,A_THICK_DEC,A_THICK_INC,A_GAP_DEC,A_GAP_INC,A_MAX_DEC,A_MAX_INC
};

typedef struct {
    Display *dpy; int screen; Window win; GC gc; Visual *visual; int depth; Colormap cmap;
    unsigned long c_bg,c_panel,c_text,c_muted,c_button,c_button2,c_seed,c_trace,c_gap,c_border,c_status;
    int ww,wh; Hit hits[MAX_HITS]; int hit_count;
    Config *configs; int config_count, config_index;
    Curve *curves; int curve_count, curve_index;
    char session_token[256]; char current_doc_sha[256]; char source_path[4096]; char status[512]; char trace_status[512];
    char *payload;
    GXImage source; GXPyramid pyr;
    double scale,offx,offy; int base_valid; Pixmap base_pix; int base_w,base_h;
    int pan_active,pan_x,pan_y; double pan_ox,pan_oy;
    int seed_mode; int has_seed1,has_seed2; GXPoint seed1,seed2;
    GXTraceSettings settings;
    GXTraceResult proposal;
    pthread_t worker; atomic_int worker_running,worker_done,cancel_flag; int worker_joinable; GXTraceResult worker_result; char worker_error[256]; int worker_ok;
    int test_mode; char test_marker[4096];
} App;

static char *dupstr(const char *s){size_t n=strlen(s)+1;char *p=malloc(n);if(p)memcpy(p,s,n);return p;}
static void free_configs(App *a){for(int i=0;i<a->config_count;i++){free(a->configs[i].doc_id);free(a->configs[i].doc_sha);free(a->configs[i].cfg_id);free(a->configs[i].name);free(a->configs[i].source_id);}free(a->configs);a->configs=NULL;a->config_count=0;}
static void free_curves(App *a){for(int i=0;i<a->curve_count;i++){free(a->curves[i].id);free(a->curves[i].name);}free(a->curves);a->curves=NULL;a->curve_count=0;}

static const char b64tab[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static char *b64enc(const unsigned char *in,size_t n){size_t outn=4*((n+2)/3);char *o=malloc(outn+1);if(!o)return NULL;size_t i=0,j=0;while(i<n){uint32_t a=i<n?in[i++]:0,b=i<n?in[i++]:0,c=i<n?in[i++]:0;uint32_t v=(a<<16)|(b<<8)|c;o[j++]=b64tab[(v>>18)&63];o[j++]=b64tab[(v>>12)&63];o[j++]=(i>n+1)?'=':b64tab[(v>>6)&63];o[j++]=(i>n)?'=':b64tab[v&63];}size_t rem=n%3;if(rem){o[outn-1]='=';if(rem==1)o[outn-2]='=';}o[outn]=0;return o;}
static int b64val(char c){if(c>='A'&&c<='Z')return c-'A';if(c>='a'&&c<='z')return c-'a'+26;if(c>='0'&&c<='9')return c-'0'+52;if(c=='+')return 62;if(c=='/')return 63;return -1;}
static char *b64dec(const char *s){size_t n=strlen(s),cap=(n/4)*3+4;unsigned char *o=malloc(cap);if(!o)return NULL;size_t j=0;int q[4];for(size_t i=0;i<n;){for(int k=0;k<4;k++){while(i<n&&(s[i]=='\r'||s[i]=='\n'||s[i]==' '))i++;if(i>=n)q[k]=-2;else if(s[i]=='='){q[k]=-2;i++;}else{q[k]=b64val(s[i++]);}}if(q[0]<0||q[1]<0)break;uint32_t v=(q[0]<<18)|(q[1]<<12)|((q[2]<0?0:q[2])<<6)|(q[3]<0?0:q[3]);o[j++]=(v>>16)&255;if(q[2]>=0)o[j++]=(v>>8)&255;if(q[3]>=0)o[j++]=v&255;}o[j]=0;return (char*)o;}

static int rpc_counter=0;
static char *rpc_call(const char *cmd,int argc,const char **argv,char *err,size_t errcap){int rid=++rpc_counter;fprintf(stdout,"REQ\t%d\t%s",rid,cmd);for(int i=0;i<argc;i++){char *b=b64enc((const unsigned char*)argv[i],strlen(argv[i]));if(!b){snprintf(err,errcap,"Out of memory.");return NULL;}fprintf(stdout,"\t%s",b);free(b);}fprintf(stdout,"\n");fflush(stdout);char *line=NULL;size_t cap=0;while(getline(&line,&cap,stdin)>=0){size_t l=strlen(line);while(l&&(line[l-1]=='\n'||line[l-1]=='\r'))line[--l]=0;if(!strncmp(line,"CONTROL\tFOCUS",13))continue;char *save=NULL,*p=strtok_r(line,"\t",&save);if(!p||strcmp(p,"RES"))continue;char *id=strtok_r(NULL,"\t",&save),*st=strtok_r(NULL,"\t",&save),*pl=strtok_r(NULL,"\t",&save);if(!id||!st||!pl||atoi(id)!=rid)continue;char *decoded=b64dec(pl);free(line);if(!decoded){snprintf(err,errcap,"Invalid host response.");return NULL;}if(!strcmp(st,"ERR")){snprintf(err,errcap,"%s",decoded);free(decoded);return NULL;}return decoded;}free(line);snprintf(err,errcap,"The GX-TXT host connection closed.");return NULL;}

static int split_record(char *line,char **kind,char ***fields,int *count){int n=0,cap=8;char **f=malloc((size_t)cap*sizeof(char*));if(!f)return 0;char *save=NULL,*p=strtok_r(line,"\t",&save);if(!p){free(f);return 0;}*kind=p;while((p=strtok_r(NULL,"\t",&save))){if(n==cap){cap*=2;char **nf=realloc(f,(size_t)cap*sizeof(char*));if(!nf){free(f);return 0;}f=nf;}f[n++]=b64dec(p);}*fields=f;*count=n;return 1;}
static void free_fields(char **f,int n){for(int i=0;i<n;i++)free(f[i]);free(f);}

static int bootstrap(App *a){char err[512]={0};char *p=rpc_call("BOOTSTRAP",0,NULL,err,sizeof(err));if(!p){snprintf(a->status,sizeof(a->status),"%s",err);return 0;}free_configs(a);char *copy=p,*save=NULL,*line=strtok_r(copy,"\n",&save);while(line){char *kind=NULL,**f=NULL;int n=0;if(split_record(line,&kind,&f,&n)){if(!strcmp(kind,"SESSION")&&n>=1)snprintf(a->session_token,sizeof(a->session_token),"%s",f[0]);else if(!strcmp(kind,"CONFIG")&&n>=6){Config *nc=realloc(a->configs,(size_t)(a->config_count+1)*sizeof(Config));if(nc){a->configs=nc;Config *c=&a->configs[a->config_count++];*c=(Config){dupstr(f[0]),dupstr(f[1]),dupstr(f[2]),dupstr(f[3]),dupstr(f[4]),!strcmp(f[5],"1")};}}free_fields(f,n);}line=strtok_r(NULL,"\n",&save);}free(p);return a->session_token[0]!=0;}

static int parse_curves(App *a,const char *json){free_curves(a);int cap=16384;JTok *t=calloc((size_t)cap,sizeof(JTok));if(!t)return 0;int n=j_parse(json,t,cap);if(n<0){free(t);snprintf(a->status,sizeof(a->status),"Unable to parse Curve Digitalizer configuration JSON.");return 0;}int arr=j_obj_get(json,t,0,"curves");if(arr<0||t[arr].type!=J_ARRAY){free(t);return 1;}for(int k=0;;k++){int ci=j_array_nth(t,arr,k);if(ci<0)break;int idt=j_obj_get(json,t,ci,"id"),nt=j_obj_get(json,t,ci,"name");if(idt<0||nt<0)continue;char id[256],name[512];j_token_str(json,&t[idt],id,sizeof(id));j_token_str(json,&t[nt],name,sizeof(name));Curve *nc=realloc(a->curves,(size_t)(a->curve_count+1)*sizeof(Curve));if(!nc)break;a->curves=nc;a->curves[a->curve_count++]=(Curve){dupstr(id),dupstr(name)};}free(t);a->curve_index=0;return 1;}

static void clear_proposal(App *a){gx_trace_result_free(&a->proposal);gx_trace_result_init(&a->proposal);snprintf(a->trace_status,sizeof(a->trace_status),"No proposal.");}
static void invalidate_base(App *a){a->base_valid=0;}
static int load_config(App *a,int index){if(index<0||index>=a->config_count)return 0;if(atomic_load(&a->worker_running)){snprintf(a->status,sizeof(a->status),"Cancel tracing before changing configuration.");return 0;}char err[512]={0};const char *args[]={a->configs[index].doc_id};char *p=rpc_call("CONFIG",1,args,err,sizeof(err));if(!p){snprintf(a->status,sizeof(a->status),"CONFIG failed: %s",err);return 0;}char *payload=NULL,*srcpath=NULL,*docsha=NULL;char *save=NULL,*line=strtok_r(p,"\n",&save);while(line){char *kind=NULL,**f=NULL;int n=0;if(split_record(line,&kind,&f,&n)){if(n>=1&&!strcmp(kind,"PAYLOAD"))payload=dupstr(f[0]);else if(n>=1&&!strcmp(kind,"SOURCE_PATH"))srcpath=dupstr(f[0]);else if(n>=1&&!strcmp(kind,"DOCUMENT_SHA"))docsha=dupstr(f[0]);free_fields(f,n);}line=strtok_r(NULL,"\n",&save);}free(p);if(!payload||!srcpath){free(payload);free(srcpath);free(docsha);snprintf(a->status,sizeof(a->status),"Selected configuration did not provide source image/context.");return 0;}
    GXImage im={0};if(!gx_image_load(srcpath,&im,err,sizeof(err))){free(payload);free(srcpath);free(docsha);snprintf(a->status,sizeof(a->status),"Image load failed: %s",err);return 0;}GXPyramid py={0};if(!gx_pyramid_build(&im,&py,err,sizeof(err))){gx_image_free(&im);free(payload);free(srcpath);free(docsha);snprintf(a->status,sizeof(a->status),"Pyramid build failed: %s",err);return 0;}gx_image_free(&a->source);gx_pyramid_free(&a->pyr);a->source=im;a->pyr=py;free(a->payload);a->payload=payload;snprintf(a->source_path,sizeof(a->source_path),"%s",srcpath);snprintf(a->current_doc_sha,sizeof(a->current_doc_sha),"%s",docsha?docsha:a->configs[index].doc_sha);free(srcpath);free(docsha);a->config_index=index;parse_curves(a,payload);a->has_seed1=a->has_seed2=0;a->seed_mode=1;clear_proposal(a);a->scale=1;a->offx=a->offy=0;invalidate_base(a);snprintf(a->status,sizeof(a->status),"Loaded %s (%d x %d), %d curve(s).",a->configs[index].name,a->source.width,a->source.height,a->curve_count);return 1;}

static unsigned long color(App *a,const char *name){XColor c,e;if(XAllocNamedColor(a->dpy,a->cmap,name,&c,&e))return c.pixel;return BlackPixel(a->dpy,a->screen);}
static void init_colors(App *a){a->c_bg=color(a,"#202020");a->c_panel=color(a,"#efefef");a->c_text=color(a,"#111111");a->c_muted=color(a,"#555555");a->c_button=color(a,"#dddddd");a->c_button2=color(a,"#c8d9ef");a->c_seed=color(a,"#ffff00");a->c_trace=color(a,"#00ffff");a->c_gap=color(a,"#ffb000");a->c_border=color(a,"#888888");a->c_status=color(a,"#e5e5e5");}
static void setfg(App *a,unsigned long c){XSetForeground(a->dpy,a->gc,c);}static void txt(App *a,int x,int y,const char *s,unsigned long c){setfg(a,c);XDrawString(a->dpy,a->win,a->gc,x,y,s,(int)strlen(s));}
static void add_hit(App *a,int x,int y,int w,int h,int action){if(a->hit_count<MAX_HITS)a->hits[a->hit_count++]=(Hit){x,y,w,h,action};}
static void button(App *a,int x,int y,int w,int h,const char *label,int action,int accent){setfg(a,accent?a->c_button2:a->c_button);XFillRectangle(a->dpy,a->win,a->gc,x,y,(unsigned)w,(unsigned)h);setfg(a,a->c_border);XDrawRectangle(a->dpy,a->win,a->gc,x,y,(unsigned)w,(unsigned)h);txt(a,x+7,y+h/2+5,label,a->c_text);add_hit(a,x,y,w,h,action);}
static const char *mode_name(GXMatchMode m){return m==GX_MATCH_GRAY?"gray":m==GX_MATCH_RGB?"rgb":m==GX_MATCH_LUMA_CHROMA?"luma_chroma":"contrast";}
static const char *dir_name(GXDirectionMode d){return d==GX_DIR_BOTH_X?"both_x":d==GX_DIR_POSITIVE_X?"positive_x":d==GX_DIR_NEGATIVE_X?"negative_x":"seed_forward";}
static void setting_row(App *a,int *y,const char *name,const char *val,int dec,int inc){txt(a,12,*y+15,name,a->c_text);button(a,205,*y,28,22,"-",dec,0);setfg(a,WhitePixel(a->dpy,a->screen));XFillRectangle(a->dpy,a->win,a->gc,238,*y,78,22);txt(a,244,*y+15,val,a->c_text);button(a,320,*y,28,22,"+",inc,0);*y+=26;}

static int choose_level(App *a){if(a->pyr.count<=1||a->scale>=1.0)return 0;double inv=1.0/a->scale;int l=0;while(l+1<a->pyr.count&&pow(2.0,l+1)<=inv*1.25)l++;return l;}
static unsigned long pack_rgb(App *a,uint8_t r,uint8_t g,uint8_t b){unsigned long masks[3]={a->visual->red_mask,a->visual->green_mask,a->visual->blue_mask};uint8_t v[3]={r,g,b};unsigned long out=0;for(int k=0;k<3;k++){unsigned long m=masks[k];int sh=0,bits=0;if(!m)continue;while(((m>>sh)&1UL)==0)sh++;unsigned long q=m>>sh;while(q&1UL){bits++;q>>=1;}unsigned long max=(1UL<<bits)-1;out|=((unsigned long)v[k]*max/255UL)<<sh;}return out;}
static void ensure_base_pix(App *a,int vw,int vh){if(a->base_pix&&a->base_w==vw&&a->base_h==vh)return;if(a->base_pix)XFreePixmap(a->dpy,a->base_pix);a->base_pix=XCreatePixmap(a->dpy,a->win,(unsigned)vw,(unsigned)vh,(unsigned)a->depth);a->base_w=vw;a->base_h=vh;a->base_valid=0;}
static void render_base(App *a){int vw=a->ww-PANEL_W,vh=a->wh-STATUS_H;if(vw<=0||vh<=0)return;ensure_base_pix(a,vw,vh);if(a->base_valid)return;setfg(a,a->c_bg);XFillRectangle(a->dpy,a->base_pix,a->gc,0,0,(unsigned)vw,(unsigned)vh);if(!a->source.rgb){a->base_valid=1;return;}int lvl=choose_level(a);GXImage *im=&a->pyr.levels[lvl];double factor=(double)(1<<lvl);char *data=calloc((size_t)vw*vh,4);if(!data)return;XImage *xi=XCreateImage(a->dpy,a->visual,(unsigned)a->depth,ZPixmap,0,data,(unsigned)vw,(unsigned)vh,32,0);if(!xi){free(data);return;}unsigned long bg=pack_rgb(a,32,32,32);for(int y=0;y<vh;y++){for(int x=0;x<vw;x++){double bx=(x-a->offx)/a->scale,by=(y-a->offy)/a->scale;unsigned long pixv=bg;if(bx>=0&&by>=0&&bx<a->source.width&&by<a->source.height){int sx=(int)(bx/factor),sy=(int)(by/factor);if(sx<0)sx=0;if(sy<0)sy=0;if(sx>=im->width)sx=im->width-1;if(sy>=im->height)sy=im->height-1;const uint8_t *p=im->rgb+(size_t)sy*im->stride+sx*3;pixv=pack_rgb(a,p[0],p[1],p[2]);}if(xi->bits_per_pixel==32)*((uint32_t*)(xi->data+(size_t)y*xi->bytes_per_line)+x)=(uint32_t)pixv;else XPutPixel(xi,x,y,pixv);}}XPutImage(a->dpy,a->base_pix,a->gc,xi,0,0,0,0,(unsigned)vw,(unsigned)vh);XDestroyImage(xi);a->base_valid=1;}
static void fit_image(App *a){if(!a->source.rgb)return;int vw=a->ww-PANEL_W,vh=a->wh-STATUS_H;if(vw<1||vh<1)return;a->scale=fmin((double)vw/a->source.width,(double)vh/a->source.height)*0.96;if(a->scale<0.01)a->scale=0.01;if(a->scale>30)a->scale=30;a->offx=(vw-a->source.width*a->scale)/2;a->offy=(vh-a->source.height*a->scale)/2;invalidate_base(a);}
static void image_to_view(App *a,double x,double y,int *cx,int *cy){*cx=PANEL_W+(int)llround(a->offx+x*a->scale);*cy=(int)llround(a->offy+y*a->scale);}
static GXPoint view_to_image(App *a,int x,int y){return (GXPoint){(x-PANEL_W-a->offx)/a->scale,(y-a->offy)/a->scale};}
static void draw_circle(App *a,int x,int y,int r,unsigned long c){setfg(a,c);XDrawArc(a->dpy,a->win,a->gc,x-r,y-r,(unsigned)(2*r),(unsigned)(2*r),0,360*64);}
static void draw_scene(App *a){render_base(a);int vw=a->ww-PANEL_W,vh=a->wh-STATUS_H;if(vw>0&&vh>0)XCopyArea(a->dpy,a->base_pix,a->win,a->gc,0,0,(unsigned)vw,(unsigned)vh,PANEL_W,0);if(a->proposal.point_count>=2){setfg(a,a->c_trace);for(size_t i=1;i<a->proposal.point_count;i++){int x1,y1,x2,y2;image_to_view(a,a->proposal.points[i-1].x,a->proposal.points[i-1].y,&x1,&y1);image_to_view(a,a->proposal.points[i].x,a->proposal.points[i].y,&x2,&y2);XDrawLine(a->dpy,a->win,a->gc,x1,y1,x2,y2);}}setfg(a,a->c_gap);for(size_t i=0;i<a->proposal.gap_count;i++){int x1,y1,x2,y2;image_to_view(a,a->proposal.gaps[i].a.x,a->proposal.gaps[i].a.y,&x1,&y1);image_to_view(a,a->proposal.gaps[i].b.x,a->proposal.gaps[i].b.y,&x2,&y2);XDrawLine(a->dpy,a->win,a->gc,x1,y1,x2,y2);}if(a->has_seed1){int x,y;image_to_view(a,a->seed1.x,a->seed1.y,&x,&y);draw_circle(a,x,y,6,a->c_seed);txt(a,x+9,y-7,"S1",a->c_seed);}if(a->has_seed2){int x,y;image_to_view(a,a->seed2.x,a->seed2.y,&x,&y);draw_circle(a,x,y,6,a->c_seed);txt(a,x+9,y-7,"S2",a->c_seed);}}
static void draw_ui(App *a){a->hit_count=0;setfg(a,a->c_panel);XFillRectangle(a->dpy,a->win,a->gc,0,0,PANEL_W,(unsigned)(a->wh-STATUS_H));int y=22;txt(a,12,y,"Curve Trace Assistant 0.5.0 - native C",a->c_text);y+=14;txt(a,12,y,"GX-TXT integration remains Tcl/API based",a->c_muted);y+=16;const char *cn=a->config_count?a->configs[a->config_index].name:"No configuration";button(a,12,y,28,24,"<",A_CFG_PREV,0);button(a,44,y,28,24,">",A_CFG_NEXT,0);txt(a,80,y+16,cn,a->c_text);y+=30;const char *cv=a->curve_count?a->curves[a->curve_index].name:"No curve";button(a,12,y,28,24,"<",A_CURVE_PREV,0);button(a,44,y,28,24,">",A_CURVE_NEXT,0);txt(a,80,y+16,cv,a->c_text);y+=32;button(a,12,y,80,24,"Reload",A_RELOAD,0);button(a,98,y,80,24,"Fit image",A_FIT,0);y+=34;txt(a,12,y,"Seed guidance",a->c_text);y+=8;button(a,12,y,102,24,"Set seed 1",A_SEED1,a->seed_mode==1);button(a,120,y,102,24,"Set seed 2",A_SEED2,a->seed_mode==2);button(a,228,y,120,24,"Clear seeds",A_CLEAR_SEEDS,0);y+=34;button(a,12,y,160,24,dir_name(a->settings.direction_mode),A_DIR,0);button(a,178,y,170,24,mode_name(a->settings.match_mode),A_MODE,0);y+=32;char b[64];snprintf(b,sizeof(b),"%.1f",a->settings.step_px);setting_row(a,&y,"Step [px]",b,A_STEP_DEC,A_STEP_INC);snprintf(b,sizeof(b),"%d",a->settings.search_radius_px);setting_row(a,&y,"Search radius",b,A_RAD_DEC,A_RAD_INC);snprintf(b,sizeof(b),"%.1f",a->settings.match_tolerance);setting_row(a,&y,"Match tolerance",b,A_TOL_DEC,A_TOL_INC);snprintf(b,sizeof(b),"%d",a->settings.sample_radius_px);setting_row(a,&y,"Sample radius",b,A_SAMPLE_DEC,A_SAMPLE_INC);snprintf(b,sizeof(b),"%d",a->settings.contrast_ring_px);setting_row(a,&y,"Contrast ring",b,A_RING_DEC,A_RING_INC);snprintf(b,sizeof(b),"%.1f",a->settings.ambiguity_margin);setting_row(a,&y,"Ambiguity margin",b,A_AMB_DEC,A_AMB_INC);snprintf(b,sizeof(b),"%.1f",a->settings.thickness_factor);setting_row(a,&y,"Thickness factor",b,A_THICK_DEC,A_THICK_INC);snprintf(b,sizeof(b),"%d",a->settings.noise_gap_steps);setting_row(a,&y,"Noise-gap lookahead",b,A_GAP_DEC,A_GAP_INC);snprintf(b,sizeof(b),"%d",a->settings.max_steps);setting_row(a,&y,"Maximum steps",b,A_MAX_DEC,A_MAX_INC);y+=4;button(a,12,y,160,28,"Trace from seed",A_TRACE,1);button(a,178,y,82,28,"Cancel",A_CANCEL,0);button(a,266,y,82,28,"Clear",A_CLEAR_PROP,0);y+=38;txt(a,12,y,a->trace_status,a->c_muted);y+=18;txt(a,12,y,"Mouse wheel: zoom | middle/right drag: pan",a->c_muted);setfg(a,a->c_status);XFillRectangle(a->dpy,a->win,a->gc,0,a->wh-STATUS_H,(unsigned)a->ww,STATUS_H);txt(a,8,a->wh-7,a->status,a->c_text);}
static void redraw(App *a){draw_scene(a);draw_ui(a);XFlush(a->dpy);}

static void *worker_main(void *arg){App *a=(App*)arg;GXTraceResult r;gx_trace_result_init(&r);char err[256]={0};GXPoint *s2=a->has_seed2?&a->seed2:NULL;int ok=gx_trace_seed_guided(&a->source,a->seed1,s2,&a->settings,&a->cancel_flag,&r,err,sizeof(err));a->worker_result=r;a->worker_ok=ok;snprintf(a->worker_error,sizeof(a->worker_error),"%s",err);atomic_store(&a->worker_done,1);return NULL;}
static void start_trace(App *a){if(!a->source.rgb||!a->curve_count){snprintf(a->status,sizeof(a->status),"Select a valid configuration and curve first.");return;}if(!a->has_seed1){snprintf(a->status,sizeof(a->status),"Set seed 1 first.");return;}if(atomic_load(&a->worker_running))return;clear_proposal(a);gx_trace_result_free(&a->worker_result);gx_trace_result_init(&a->worker_result);a->worker_error[0]=0;a->worker_ok=0;atomic_store(&a->cancel_flag,0);atomic_store(&a->worker_done,0);atomic_store(&a->worker_running,1);if(pthread_create(&a->worker,NULL,worker_main,a)!=0){atomic_store(&a->worker_running,0);snprintf(a->status,sizeof(a->status),"Unable to start native tracing worker.");return;}a->worker_joinable=1;snprintf(a->trace_status,sizeof(a->trace_status),"Tracing in worker thread... UI remains interactive.");}
static void finish_worker(App *a){if(!atomic_load(&a->worker_done))return;if(a->worker_joinable){pthread_join(a->worker,NULL);a->worker_joinable=0;}atomic_store(&a->worker_running,0);atomic_store(&a->worker_done,0);if(a->worker_ok){gx_trace_result_free(&a->proposal);a->proposal=a->worker_result;gx_trace_result_init(&a->worker_result);snprintf(a->trace_status,sizeof(a->trace_status),"%zu points | %s | L: %.70s | R: %.70s",a->proposal.point_count,a->proposal.target_description,a->proposal.stop_left,a->proposal.stop_right);snprintf(a->status,sizeof(a->status),a->proposal.cancelled?"Tracing cancelled; partial proposal shown.":"Native trace proposal ready.");}else{gx_trace_result_free(&a->worker_result);snprintf(a->status,sizeof(a->status),"Tracing failed: %s",a->worker_error);snprintf(a->trace_status,sizeof(a->trace_status),"No proposal.");}}

static int hit_action(App *a,int x,int y){for(int i=a->hit_count-1;i>=0;i--){Hit *h=&a->hits[i];if(x>=h->x&&y>=h->y&&x<h->x+h->w&&y<h->y+h->h)return h->action;}return 0;}
static void clamp_settings(App *a){char e[128];if(a->settings.sample_radius_px>=a->settings.contrast_ring_px)a->settings.contrast_ring_px=a->settings.sample_radius_px+1;if(!gx_trace_settings_validate(&a->settings,e,sizeof(e)))snprintf(a->status,sizeof(a->status),"%s",e);}
static void action(App *a,int ac){switch(ac){case A_CFG_PREV:if(a->config_count)load_config(a,(a->config_index+a->config_count-1)%a->config_count);break;case A_CFG_NEXT:if(a->config_count)load_config(a,(a->config_index+1)%a->config_count);break;case A_CURVE_PREV:if(a->curve_count){a->curve_index=(a->curve_index+a->curve_count-1)%a->curve_count;clear_proposal(a);}break;case A_CURVE_NEXT:if(a->curve_count){a->curve_index=(a->curve_index+1)%a->curve_count;clear_proposal(a);}break;case A_RELOAD:bootstrap(a);if(a->config_count)load_config(a,a->config_index<a->config_count?a->config_index:0);break;case A_FIT:fit_image(a);break;case A_SEED1:a->seed_mode=1;break;case A_SEED2:a->seed_mode=2;break;case A_CLEAR_SEEDS:a->has_seed1=a->has_seed2=0;clear_proposal(a);break;case A_TRACE:start_trace(a);break;case A_CANCEL:atomic_store(&a->cancel_flag,1);break;case A_CLEAR_PROP:clear_proposal(a);break;case A_DIR:a->settings.direction_mode=(GXDirectionMode)((a->settings.direction_mode+1)%4);break;case A_MODE:a->settings.match_mode=(GXMatchMode)((a->settings.match_mode+1)%4);break;case A_STEP_DEC:a->settings.step_px=fmax(.5,a->settings.step_px-.5);break;case A_STEP_INC:a->settings.step_px=fmin(20,a->settings.step_px+.5);break;case A_RAD_DEC:if(a->settings.search_radius_px>1)a->settings.search_radius_px--;break;case A_RAD_INC:if(a->settings.search_radius_px<80)a->settings.search_radius_px++;break;case A_TOL_DEC:a->settings.match_tolerance=fmax(.5,a->settings.match_tolerance-2);break;case A_TOL_INC:a->settings.match_tolerance=fmin(512,a->settings.match_tolerance+2);break;case A_SAMPLE_DEC:if(a->settings.sample_radius_px>0)a->settings.sample_radius_px--;break;case A_SAMPLE_INC:if(a->settings.sample_radius_px<8)a->settings.sample_radius_px++;break;case A_RING_DEC:if(a->settings.contrast_ring_px>2)a->settings.contrast_ring_px--;break;case A_RING_INC:if(a->settings.contrast_ring_px<30)a->settings.contrast_ring_px++;break;case A_AMB_DEC:a->settings.ambiguity_margin=fmax(0,a->settings.ambiguity_margin-1);break;case A_AMB_INC:a->settings.ambiguity_margin=fmin(128,a->settings.ambiguity_margin+1);break;case A_THICK_DEC:a->settings.thickness_factor=fmax(1.2,a->settings.thickness_factor-.1);break;case A_THICK_INC:a->settings.thickness_factor=fmin(8,a->settings.thickness_factor+.1);break;case A_GAP_DEC:if(a->settings.noise_gap_steps>0)a->settings.noise_gap_steps--;break;case A_GAP_INC:if(a->settings.noise_gap_steps<3)a->settings.noise_gap_steps++;break;case A_MAX_DEC:a->settings.max_steps=a->settings.max_steps>101?a->settings.max_steps-100:1;break;case A_MAX_INC:a->settings.max_steps=a->settings.max_steps<19901?a->settings.max_steps+100:20000;break;}clamp_settings(a);redraw(a);}

static void handle_button(App *a,XButtonEvent *e){if(e->x<PANEL_W){action(a,hit_action(a,e->x,e->y));return;}if(e->button==1&&a->source.rgb){GXPoint p=view_to_image(a,e->x,e->y);if(p.x>=0&&p.y>=0&&p.x<a->source.width&&p.y<a->source.height){if(a->seed_mode==1){a->seed1=p;a->has_seed1=1;}else{a->seed2=p;a->has_seed2=1;}clear_proposal(a);redraw(a);}}else if(e->button==2||e->button==3){a->pan_active=1;a->pan_x=e->x;a->pan_y=e->y;a->pan_ox=a->offx;a->pan_oy=a->offy;}else if(e->button==4||e->button==5){double factor=e->button==4?1.18:1/1.18;GXPoint before=view_to_image(a,e->x,e->y);double ns=fmax(.01,fmin(30,a->scale*factor));a->scale=ns;a->offx=(e->x-PANEL_W)-before.x*a->scale;a->offy=e->y-before.y*a->scale;invalidate_base(a);redraw(a);}}
static void handle_key(App *a,XKeyEvent *e){char buf[8];KeySym ks;XLookupString(e,buf,sizeof(buf),&ks,NULL);if(ks==XK_Escape)atomic_store(&a->cancel_flag,1);else if(ks==XK_F||ks==XK_f){fit_image(a);redraw(a);}else if(ks==XK_1){a->seed_mode=1;redraw(a);}else if(ks==XK_2){a->seed_mode=2;redraw(a);}else if(ks==XK_T||ks==XK_t){start_trace(a);redraw(a);}else if(ks==XK_C||ks==XK_c){clear_proposal(a);redraw(a);}}

static int auto_test(App *a){if(!a->test_mode||!a->source.rgb||!a->curve_count)return 0;int x1=(int)(a->source.width*.12),x2=(int)(a->source.width*.20);int besty1=0,besty2=0,best1=999,best2=999;for(int y=0;y<a->source.height;y++){const uint8_t *p=a->source.rgb+(size_t)y*a->source.stride+x1*3;int g=(77*p[0]+150*p[1]+29*p[2])>>8;if(g<best1){best1=g;besty1=y;}p=a->source.rgb+(size_t)y*a->source.stride+x2*3;g=(77*p[0]+150*p[1]+29*p[2])>>8;if(g<best2){best2=g;besty2=y;}}a->seed1=(GXPoint){x1,besty1};a->seed2=(GXPoint){x2,besty2};a->has_seed1=a->has_seed2=1;a->settings.direction_mode=GX_DIR_POSITIVE_X;a->settings.match_mode=GX_MATCH_GRAY;a->settings.match_tolerance=55;a->settings.search_radius_px=8;start_trace(a);a->test_mode=2;return 1;}
static void test_finish(App *a){if(a->test_mode!=2||atomic_load(&a->worker_running))return;FILE *f=fopen(a->test_marker,"w");if(f){if(a->proposal.point_count>=20){double mx=0;for(size_t i=0;i<a->proposal.point_count;i++)if(a->proposal.points[i].x>mx)mx=a->proposal.points[i].x;if(mx>a->source.width*.72)fprintf(f,"PASS\n");else fprintf(f,"FAIL: trace did not progress across image\n");}else fprintf(f,"FAIL: proposal too short: %zu\n",a->proposal.point_count);fclose(f);}XDestroyWindow(a->dpy,a->win);}

static void cleanup(App *a){if(atomic_load(&a->worker_running)){atomic_store(&a->cancel_flag,1);if(a->worker_joinable)pthread_join(a->worker,NULL);}gx_trace_result_free(&a->worker_result);gx_trace_result_free(&a->proposal);if(a->base_pix)XFreePixmap(a->dpy,a->base_pix);gx_pyramid_free(&a->pyr);gx_image_free(&a->source);free(a->payload);free_configs(a);free_curves(a);if(a->gc)XFreeGC(a->dpy,a->gc);if(a->dpy)XCloseDisplay(a->dpy);}

int main(int argc,char **argv){if(argc>1&&!strcmp(argv[1],"--version")){puts(VERSION);return 0;}if(argc>1&&!strcmp(argv[1],"--self-test")){GXImage im={160,100,480,malloc(48000)};memset(im.rgb,240,48000);for(int x=5;x<155;x++){int y=50+(int)(12*sin(x/25.0));for(int d=-1;d<=1;d++){uint8_t *p=im.rgb+(y+d)*im.stride+x*3;p[0]=p[1]=p[2]=20;}}GXTraceSettings s;gx_trace_settings_default(&s);s.match_tolerance=55;GXTraceResult r;gx_trace_result_init(&r);char err[256]={0};int ok=gx_trace_seed_guided(&im,(GXPoint){25,60},NULL,&s,NULL,&r,err,sizeof(err));if(ok&&r.point_count>20) printf("PASS native self-test %zu points\n",r.point_count); else printf("FAIL native self-test: %s (%zu points)\n",err,r.point_count);int rc=ok&&r.point_count>20?0:2;gx_trace_result_free(&r);free(im.rgb);return rc;}
    App a;memset(&a,0,sizeof(a));gx_trace_settings_default(&a.settings);gx_trace_result_init(&a.proposal);gx_trace_result_init(&a.worker_result);snprintf(a.status,sizeof(a.status),"Starting native Curve Trace Assistant...");snprintf(a.trace_status,sizeof(a.trace_status),"No proposal.");const char *sc=getenv("GX_TRACE_ASSISTANT_TEST_SCENARIO"),*mk=getenv("GX_TRACE_ASSISTANT_TEST_MARKER");if(sc&&*sc){a.test_mode=1;if(mk)snprintf(a.test_marker,sizeof(a.test_marker),"%s",mk);}if(!bootstrap(&a)){fprintf(stderr,"%s\n",a.status);cleanup(&a);return 2;}
    a.dpy=XOpenDisplay(NULL);if(!a.dpy){fprintf(stderr,"Unable to open X display.\n");cleanup(&a);return 2;}a.screen=DefaultScreen(a.dpy);a.visual=DefaultVisual(a.dpy,a.screen);a.depth=DefaultDepth(a.dpy,a.screen);a.cmap=DefaultColormap(a.dpy,a.screen);a.ww=1320;a.wh=820;a.win=XCreateSimpleWindow(a.dpy,RootWindow(a.dpy,a.screen),20,20,a.ww,a.wh,1,BlackPixel(a.dpy,a.screen),WhitePixel(a.dpy,a.screen));XStoreName(a.dpy,a.win,APP_TITLE);XSelectInput(a.dpy,a.win,ExposureMask|StructureNotifyMask|ButtonPressMask|ButtonReleaseMask|PointerMotionMask|KeyPressMask);a.gc=XCreateGC(a.dpy,a.win,0,NULL);init_colors(&a);Atom del=XInternAtom(a.dpy,"WM_DELETE_WINDOW",False);XSetWMProtocols(a.dpy,a.win,&del,1);XMapWindow(a.dpy,a.win);if(a.config_count)load_config(&a,0);fit_image(&a);redraw(&a);auto_test(&a);
    int running=1,xfd=ConnectionNumber(a.dpy);while(running){finish_worker(&a);test_finish(&a);while(XPending(a.dpy)){XEvent e;XNextEvent(a.dpy,&e);if(e.type==Expose)redraw(&a);else if(e.type==ConfigureNotify){a.ww=e.xconfigure.width;a.wh=e.xconfigure.height;invalidate_base(&a);redraw(&a);}else if(e.type==ButtonPress)handle_button(&a,&e.xbutton);else if(e.type==ButtonRelease){if(e.xbutton.button==2||e.xbutton.button==3)a.pan_active=0;}else if(e.type==MotionNotify&&a.pan_active){a.offx=a.pan_ox+e.xmotion.x-a.pan_x;a.offy=a.pan_oy+e.xmotion.y-a.pan_y;invalidate_base(&a);redraw(&a);}else if(e.type==KeyPress)handle_key(&a,&e.xkey);else if(e.type==ClientMessage&&(Atom)e.xclient.data.l[0]==del)running=0;else if(e.type==DestroyNotify)running=0;}struct timeval tv={0,20000};fd_set fds;FD_ZERO(&fds);FD_SET(xfd,&fds);select(xfd+1,&fds,NULL,NULL,&tv);}cleanup(&a);return 0;}
